#include "coh_class_level.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
static unsigned long long checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"classlevel %d: %s\n",__LINE__,#x);exit(1);}}while(0)
static CohClassDictionary classes;static CohClassWorkspace cw;static CohPowerCategoryDictionary cats;static CohPowerCategoryWorkspace pw;static CohClassLevel out,old;static CohClassLevelWorkspace work;
static CohStatus digest(void*ctx,CohBytes b,uint8_t h[32]){(void)ctx;SHA256(b.data,b.size,h);return COH_OK;}
static uint32_t word(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static CohStatus project(uint32_t which,uint32_t level,size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));old=out;CohStatus s=coh_class_level_read(&classes,&cats,which,level,&out,&work,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&old,&out,sizeof(out)));return s;}
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");CHECK(f);uint32_t size=word(f);uint8_t*catbytes=malloc(size);CHECK(catbytes&&fread(catbytes,1,size,f)==size);uint8_t hash[32];SHA256(catbytes,size,hash);CohCostumeImportDigest provider={digest,NULL,0,0};CHECK(coh_power_categories_read((CohBytes){catbytes,size},11,hash,&provider,&cats,&pw,COH_CATEGORY_RAM_MAX,0)==COH_OK);free(catbytes);unsigned files=word(f),cases=0;
for(unsigned fi=0;fi<files;fi++){size=word(f);uint8_t*data=malloc(size);CHECK(data&&fread(data,1,size,f)==size);SHA256(data,size,hash);CHECK(coh_classes_read((CohBytes){data,size},21+fi,hash,&provider,&classes,&cw,COH_CLASS_RAM_MAX,0)==COH_OK);unsigned n=word(f);for(unsigned ci=0;ci<n;ci++){uint32_t which=word(f),level=word(f),levels=word(f),bytes=word(f),categories[4];for(unsigned i=0;i<4;i++)categories[i]=word(f);CHECK(project(which,level,COH_CLASS_LEVEL_RAM_MAX,0)==COH_OK);CHECK(out.class_index==which&&out.level==level&&out.levels==levels&&out.table_bytes==bytes&&!memcmp(out.category_index,categories,sizeof(categories))&&out.historical_projection_validated&&!out.runtime_generation&&!out.actor_authority&&out.class_lease==21+fi&&out.category_lease==11&&!memcmp(out.class_sha256,hash,32)&&!memcmp(out.category_sha256,cats.input_sha256,32));for(unsigned i=0;i<6;i++)for(unsigned j=0;j<115;j++){uint32_t expected=word(f);if(out.attributes[i][j]!=expected)fprintf(stderr,"file%u class%u level%u row%u attr%u native%x expected%x\n",fi,which,level,i,j,out.attributes[i][j],expected);CHECK(out.attributes[i][j]==expected);}size_t exact=sizeof(classes)+sizeof(cats)+sizeof(out)+sizeof(work)+size+COH_CLASS_LEVEL_STACK_RESERVE;CHECK(project(which,level,exact,0)==COH_OK);CHECK(project(which,level,exact,1)==COH_LIMIT);CHECK(project(which,levels,COH_CLASS_LEVEL_RAM_MAX,0)==COH_UNSUPPORTED);CHECK(project(which,UINT32_MAX,COH_CLASS_LEVEL_RAM_MAX,0)==COH_UNSUPPORTED);cases++;}CHECK(project(classes.count,0,COH_CLASS_LEVEL_RAM_MAX,0)==COH_STATE);CHECK(coh_class_level_read(&classes,&cats,0,0,&out,(CohClassLevelWorkspace*)&out,COH_CLASS_LEVEL_RAM_MAX,0)==COH_INVALID);CohClassSpan saved=classes.entries[0].fields[27];classes.entries[0].fields[27].end=UINT32_MAX;CHECK(project(0,0,COH_CLASS_LEVEL_RAM_MAX,0)==COH_STATE);classes.entries[0].fields[27]=saved;free(data);}
CHECK(fgetc(f)==EOF);fclose(f);printf("{\"checks\":%llu,\"cases\":%u,\"projection_bytes\":%zu,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,cases,sizeof(out));return 0;}
